WITH profiles(id,created_at) AS(VALUES ('00000000-0000-4000-8000-000000000001'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000002'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000003'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000005'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000006'::uuid,'2026-11-20T10:05:00Z'::timestamptz),('00000000-0000-4000-8000-000000000004'::uuid,'2026-10-01T00:00:00Z'::timestamptz)), events(id,session_id,name,path,created_at,user_id,metadata) AS(VALUES ('00000000-0000-4000-8000-000000000100'::uuid,'a','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T10:00:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000101'::uuid,'a','landing_session_started','/ignored-duplicate','2026-11-20T10:01:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"chatgpt.com"}'::jsonb),('00000000-0000-4000-8000-000000000102'::uuid,'a','signup','/signup','2026-11-20T10:05:00Z'::timestamptz,'00000000-0000-4000-8000-000000000001'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000000103'::uuid,'b','landing_session_started','/how-much-do-instagram-reels-pay','2026-11-21T11:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000001'::uuid,'{"is_bot":false,"referrer_host":"chatgpt.com"}'::jsonb),('00000000-0000-4000-8000-000000000104'::uuid,'c','landing_session_started','/how-much-do-instagram-reels-pay','2026-11-20T11:00:00Z'::timestamptz,NULL::uuid,'{"is_bot":false,"referrer_host":"chatgpt.com"}'::jsonb),('00000000-0000-4000-8000-000000000105'::uuid,'c','signup','/signup','2026-11-20T11:05:00Z'::timestamptz,'00000000-0000-4000-8000-000000000002'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000000106'::uuid,'staff','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T12:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000003'::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000107'::uuid,'old','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T12:10:00Z'::timestamptz,'00000000-0000-4000-8000-000000000004'::uuid,'{"is_bot":false,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000108'::uuid,'bot','landing_session_started','/how-much-do-youtube-shorts-pay','2026-11-20T12:20:00Z'::timestamptz,'00000000-0000-4000-8000-000000000005'::uuid,'{"is_bot":true,"referrer_host":"bing.com"}'::jsonb),('00000000-0000-4000-8000-000000000109'::uuid,'ambiguous','landing_session_started','/how-much-do-instagram-reels-pay','2026-11-20T13:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000002'::uuid,'{"is_bot":false,"referrer_host":"chatgpt.com"}'::jsonb),('00000000-0000-4000-8000-000000000110'::uuid,'ambiguous','session','/studio','2026-11-20T13:01:00Z'::timestamptz,'00000000-0000-4000-8000-000000000006'::uuid,'{}'::jsonb),('00000000-0000-4000-8000-000000000111'::uuid,'missing','landing_session_started','/how-much-do-instagram-reels-pay','2026-11-20T13:10:00Z'::timestamptz,NULL::uuid,'{"is_bot":false}'::jsonb),('00000000-0000-4000-8000-000000000112'::uuid,'a','payment_success','/api/stripe/webhook','2026-11-20T14:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000001'::uuid,'{"source":"stripe_webhook","stripe_livemode":true,"stripe_payment_status":"paid","amount_total":100}'::jsonb),('00000000-0000-4000-8000-000000000113'::uuid,'a','payment_success','/api/stripe/webhook','2026-11-20T14:00:00Z'::timestamptz,'00000000-0000-4000-8000-000000000001'::uuid,'{"source":"stripe_webhook","stripe_livemode":true,"stripe_payment_status":"paid","amount_total":100}'::jsonb),('00000000-0000-4000-8000-000000000114'::uuid,'c','payment_success','/checkout/success','2026-11-20T14:20:00Z'::timestamptz,'00000000-0000-4000-8000-000000000002'::uuid,'{"source":"client","stripe_livemode":false,"stripe_payment_status":"unpaid","amount_total":100}'::jsonb)), videos(user_id,created_at,status) AS(VALUES('00000000-0000-4000-8000-000000000001'::uuid,'2026-11-20T15:00:00Z'::timestamptz,'completed'),('00000000-0000-4000-8000-000000000001'::uuid,'2026-11-20T16:00:00Z'::timestamptz,'completed'),('00000000-0000-4000-8000-000000000002'::uuid,'2026-11-20T15:00:00Z'::timestamptz,'failed')), b AS (SELECT '2026-11-24T16:01:33.742416+00:00'::timestamptz cut), internal_profiles AS(SELECT '00000000-0000-4000-8000-000000000003'::uuid id),
raw AS (SELECT DISTINCT ON(session_id) id,session_id,created_at,split_part(path,'?',1) path,metadata FROM events,b WHERE name='landing_session_started' AND session_id IS NOT NULL AND created_at>=cut-interval '30 days' AND created_at<cut ORDER BY session_id,created_at,id),
linked AS (SELECT r.*,u.ids,u.n,u.internal FROM raw r CROSS JOIN b CROSS JOIN LATERAL(SELECT array_agg(DISTINCT e.user_id) FILTER(WHERE e.user_id IS NOT NULL) ids,count(DISTINCT e.user_id) n,bool_or(i.id IS NOT NULL) internal FROM events e LEFT JOIN internal_profiles i ON i.id=e.user_id WHERE e.session_id=r.session_id AND e.created_at>=r.created_at AND e.created_at<cut)u WHERE metadata->>'is_bot'='false' AND NOT coalesce(u.internal,false)),
first_account AS(SELECT DISTINCT ON(p.id) p.id uid,l.session_id,p.created_at signed_at FROM linked l JOIN profiles p ON p.id=ANY(l.ids) CROSS JOIN b WHERE l.n=1 AND p.created_at>=cut-interval '30 days' AND p.created_at<cut AND p.id NOT IN(SELECT id FROM internal_profiles) ORDER BY p.id,l.created_at,l.id),
origins AS(SELECT l.*,CASE
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('chatgpt','chatgpt.com','www.chatgpt.com') OR coalesce(metadata->>'utm_source','') ILIKE '%chatgpt%' THEN 'chatgpt_explicito'
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('bing','bing.com','www.bing.com') OR lower(coalesce(metadata->>'utm_source',''))='bing' THEN CASE WHEN lower(coalesce(metadata->>'utm_medium',''))='cpc' THEN 'bing_pago' ELSE 'bing_explicito' END
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('google.com','www.google.com','google') OR lower(coalesce(metadata->>'utm_source',''))='google' THEN 'google'
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('duckduckgo.com','www.duckduckgo.com') OR lower(coalesce(metadata->>'utm_source',''))='duckduckgo' THEN 'duckduckgo'
 WHEN lower(coalesce(metadata->>'referrer_host','')) IN ('youtube.com','www.youtube.com','m.youtube.com','youtu.be') OR lower(coalesce(metadata->>'utm_source',''))='youtube' THEN 'youtube'
 WHEN lower(coalesce(metadata->>'utm_source',''))='affiliate' THEN 'afiliado_rotulado'
 WHEN lower(coalesce(metadata->>'utm_source','')) IN ('instagram','ig') THEN 'instagram'
 WHEN nullif(metadata->>'referrer_host','') IS NULL AND nullif(metadata->>'utm_source','') IS NULL THEN 'origem_nao_gravada'
 ELSE 'outra_origem_gravada' END origin FROM linked l),
film AS(SELECT a.uid,min(v.created_at) first_completed_request_at FROM first_account a JOIN videos v ON v.user_id=a.uid CROSS JOIN b WHERE v.status='completed' AND v.created_at>=a.signed_at AND v.created_at<cut GROUP BY a.uid),
paid AS(SELECT DISTINCT e.user_id uid FROM events e JOIN first_account a ON a.uid=e.user_id CROSS JOIN b WHERE e.name='payment_success' AND e.path='/api/stripe/webhook' AND e.metadata->>'source'='stripe_webhook' AND e.metadata->>'stripe_livemode'='true' AND e.metadata->>'stripe_payment_status'='paid' AND e.metadata->>'amount_total' ~ '^[0-9]+$' AND (e.metadata->>'amount_total')::numeric>0 AND e.created_at>=a.signed_at AND e.created_at<cut),
groups AS(SELECT l.origin,l.path,count(*) sessions,count(DISTINCT a.uid) accounts,count(DISTINCT f.uid) first_completed_requests,count(DISTINCT p.uid) paid_people,count(*) FILTER(WHERE l.n>1) ambiguous_sessions FROM origins l LEFT JOIN first_account a ON a.session_id=l.session_id LEFT JOIN film f ON f.uid=a.uid LEFT JOIN paid p ON p.uid=a.uid GROUP BY l.origin,l.path)
SELECT jsonb_build_object('start',(SELECT cut-interval '30 days' FROM b),'cut',(SELECT cut FROM b),'rows',(SELECT jsonb_agg(to_jsonb(g) ORDER BY accounts DESC,sessions DESC,path) FROM groups g)) measurement